 * A token bucket: a per-key allowance that refills over time and is spent
 * one whole token at a time.
 *
 * The per-key allowance is tracked as `tokens * per`, an integer, so that
 * the exact fraction `refill * n / per` added by an `n`-tick advance never
 * needs rounding.
 */
export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.states = new Map()
  }

  #state(key) {
    let state = this.states.get(key)
    if (!state) {
      state = { numerator: this.capacity * this.per, lastTick: null }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#state(key)
    if (state.lastTick === null) {
      state.lastTick = tick
      return
    }
    const delta = tick - state.lastTick
    if (delta > 0n) {
      const cap = this.capacity * this.per
      state.numerator += this.refill * delta
      if (state.numerator > cap) state.numerator = cap
      state.lastTick = tick
    }
  }

  allow(key) {
    return this.#state(key).numerator >= this.per
  }

  record(key) {
    this.#state(key).numerator -= this.per
  }
}

/**
 * A sliding window: a per-key log of recorded ticks, pruned to the span
 * ending at the current tick.
 */
export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  #state(key) {
    let state = this.states.get(key)
    if (!state) {
      state = []
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const ticks = this.#state(key)
    const threshold = tick - this.span
    let i = 0
    while (i < ticks.length && ticks[i] <= threshold) i++
    if (i > 0) ticks.splice(0, i)
  }

  allow(key) {
    return BigInt(this.#state(key).length) < this.limit
  }

  record(key, tick) {
    this.#state(key).push(tick)
  }
}
"}

