{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-il4NWj/src/limiter.js","content":"/**
 * The limiter file format: parsing and simulating a limiter file line by
 * line, producing either a replay log or a per-key summary.
 */
import { TokenBucket, SlidingWindow } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_./:-]+$/
const INTEGER_RE = /^(0|[1-9][0-9]*)$/

class LineError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

function fail(line, reason) {
  throw new LineError(line, reason)
}

function parseIntField(line, token, field, least) {
  if (!INTEGER_RE.test(token)) fail(line, `${field} must be an integer of at least ${least}`)
  const value = BigInt(token)
  if (value < least) fail(line, `${field} must be an integer of at least ${least}`)
  return value
}

function validateName(line, token, kind) {
  if (!NAME_RE.test(token)) fail(line, `invalid ${kind} ${token}`)
}

/**
 * Runs a limiter file against a mode ('replay' or 'summary') and returns
 * the resulting output text. Throws a `LineError` on the first invalid
 * line, per the written format.
 */
export function run(text, mode) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const policies = new Map()
  const routes = []
  let seenEvent = false
  let lastTick = null

  const replayLines = []
  const perKey = new Map()
  let totalAllowed = 0n
  let totalDenied = 0n

  function keyCounts(key) {
    let counts = perKey.get(key)
    if (!counts) {
      counts = { allowed: 0n, denied: 0n }
      perKey.set(key, counts)
    }
    return counts
  }

  function findRoute(key) {
    let best = null
    for (const route of routes) {
      if (key.startsWith(route.prefix)) {
        if (best === null || route.prefix.length > best.prefix.length) best = route
      }
    }
    return best
  }

  rawLines.forEach((rawLine, index) => {
    const lineNo = index + 1
    const trimmed = rawLine.trim()
    if (trimmed === '' || trimmed.startsWith('#')) return

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive !== 'bucket' && directive !== 'window' && directive !== 'route' && directive !== 'event') {
      fail(lineNo, `unknown directive ${directive}`)
    }

    if (directive !== 'event' && seenEvent) {
      fail(lineNo, 'declarations must come before the first event')
    }

    if (directive === 'bucket') {
      if (tokens.length !== 5) fail(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      const [, name, capacityTok, refillTok, perTok] = tokens
      validateName(lineNo, name, 'policy name')
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      const capacity = parseIntField(lineNo, capacityTok, 'capacity', 1n)
      const refill = parseIntField(lineNo, refillTok, 'refill', 0n)
      const per = parseIntField(lineNo, perTok, 'per', 1n)
      policies.set(name, new TokenBucket(capacity, refill, per))
    } else if (directive === 'window') {
      if (tokens.length !== 4) fail(lineNo, 'expected window <name> <limit> <span>')
      const [, name, limitTok, spanTok] = tokens
      validateName(lineNo, name, 'policy name')
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      const limit = parseIntField(lineNo, limitTok, 'limit', 0n)
      const span = parseIntField(lineNo, spanTok, 'span', 1n)
      policies.set(name, new SlidingWindow(limit, span))
    } else if (directive === 'route') {
      if (tokens.length < 3) fail(lineNo, 'expected route <prefix> <policy>...')
      const prefix = tokens[1]
      validateName(lineNo, prefix, 'route prefix')
      if (routes.some((r) => r.prefix === prefix)) fail(lineNo, `prefix ${prefix} is routed twice`)
      const policyNames = tokens.slice(2)
      const routePolicies = policyNames.map((name) => {
        const policy = policies.get(name)
        if (!policy) fail(lineNo, `unknown policy ${name}`)
        return { name, policy }
      })
      routes.push({ prefix, policies: routePolicies })
    } else if (directive === 'event') {
      if (tokens.length !== 3) fail(lineNo, 'expected event <tick> <key>')
      const [, tickTok, key] = tokens
      const tick = parseIntField(lineNo, tickTok, 'tick', 0n)
      validateName(lineNo, key, 'key')
      if (lastTick !== null && tick < lastTick) fail(lineNo, `tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      seenEvent = true

      const route = findRoute(key)
      let allowed
      let denyName = null
      if (route === null) {
        allowed = true
      } else {
        for (const { policy } of route.policies) policy.advance(key, tick)
        for (const { name, policy } of route.policies) {
          if (!policy.allow(key)) {
            denyName = name
            break
          }
        }
        allowed = denyName === null
        if (allowed) {
          for (const { policy } of route.policies) policy.record(key, tick)
        }
      }

      const counts = keyCounts(key)
      if (allowed) {
        counts.allowed += 1n
        totalAllowed += 1n
        replayLines.push(`${tick} ${key} allow`)
      } else {
        counts.denied += 1n
        totalDenied += 1n
        replayLines.push(`${tick} ${key} deny ${denyName}`)
      }
    }
  })

  if (mode === 'replay') {
    return replayLines.map((line) => line + '\n').join('')
  }

  const lines = []
  for (const key of [...perKey.keys()].sort()) {
    const counts = perKey.get(key)
    lines.push(`${key} allowed=${counts.allowed} denied=${counts.denied}`)
  }
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  return lines.map((line) => line + '\n').join('')
}

export { LineError }
"}

